package com.arjunren.hospital;
import com.arjunren.hospital.domain.*;import com.arjunren.hospital.dto.Dtos.*;import com.arjunren.hospital.entity.*;import com.arjunren.hospital.exception.DomainException;import com.arjunren.hospital.repository.*;import com.arjunren.hospital.service.HospitalService;import java.time.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import static org.assertj.core.api.Assertions.*;
@SpringBootTest@ActiveProfiles("test")class HospitalServiceTests{@Autowired UserRepository users;@Autowired DoctorRepository doctors;@Autowired PatientRepository patients;@Autowired AppointmentRepository appointments;@Autowired HospitalService service;AppUser admin,doctorUser,patientUser,other;DoctorProfile doctor;PatientProfile patient;@BeforeEach void setup(){appointments.deleteAll();doctors.deleteAll();patients.deleteAll();users.deleteAll();admin=users.save(new AppUser("a@e.com","x","Admin",Role.ADMIN));doctorUser=users.save(new AppUser("d@e.com","x","Doctor",Role.DOCTOR));patientUser=users.save(new AppUser("p@e.com","x","Patient",Role.PATIENT));other=users.save(new AppUser("o@e.com","x","Other",Role.PATIENT));doctor=doctors.save(new DoctorProfile(doctorUser,"L1","General",30));patient=patients.save(new PatientProfile(patientUser,"M1",LocalDate.of(1990,1,1),null));patients.save(new PatientProfile(other,"M2",LocalDate.of(1991,1,1),null));}@Test void preventsDoctorOverlap(){Instant s=Instant.now().plusSeconds(3600);service.schedule(new AppointmentCreate(doctor.getId(),null,s,"Visit"),patientUser);assertThatThrownBy(()->service.schedule(new AppointmentCreate(doctor.getId(),patients.findByUserId(other.getId()).orElseThrow().getId(),s.plusSeconds(600),"Other"),admin)).isInstanceOf(DomainException.class).hasMessageContaining("unavailable");}@Test void patientOwnershipIsEnforced(){var a=service.schedule(new AppointmentCreate(doctor.getId(),null,Instant.now().plusSeconds(3600),"Visit"),patientUser);assertThatThrownBy(()->service.get(a.id(),other)).isInstanceOf(DomainException.class);}@Test void doctorCompletesOwnAppointment(){var a=service.schedule(new AppointmentCreate(doctor.getId(),null,Instant.now().plusSeconds(3600),"Visit"),patientUser);assertThat(service.complete(a.id(),new CompleteRequest("Healthy","Rest"),doctorUser).status()).isEqualTo(AppointmentStatus.COMPLETED);}@Test void doctorsCannotBookAppointments(){assertThatThrownBy(()->service.schedule(new AppointmentCreate(doctor.getId(),patient.getId(),Instant.now().plusSeconds(3600),"Visit"),doctorUser)).isInstanceOf(DomainException.class);}}

